pub fn extract_mandate_id(
    &self,
    mandate_reference: &MandateReferenceId,
) -> CustomResult<String, errors::IntegrationError> {
    match mandate_reference {
        MandateReferenceId::ConnectorMandateId(connector_mandate_ref) => {
