    for {ConnectorName}<T>
{
    fn get_headers(
        &self,
        req: &RouterDataV2<SubmitEvidence, DisputeFlowData, SubmitEvidenceData, DisputeResponseData>,
    ) -> CustomResult<Vec<(String, Maskable<String>)>, errors::IntegrationError> {
        let mut header = vec![(
